insert into public.guides (agency_id, slug, title, audience, language, services, content, version, is_published) values
(7, 'joey-trafego-en', 'How it works: paid ads', 'cliente', 'en', array['Tráfego Pago']::text[], '{"hero": {"eyebrow": "Pouch · Client guide", "title": "Your ads, from the first click to the sale.", "text": "This guide shows how to track your ads, approve the creatives and log your contacts in Pouch. All from your phone."}, "steps": [{"title": "Portal", "who": "You", "tone": "cliente"}, {"title": "Ads", "who": "You", "tone": "cliente"}, {"title": "Approve ads", "who": "You", "tone": "cliente"}, {"title": "CRM", "who": "You", "tone": "cliente"}], "sections": [{"who": "You", "tone": "cliente", "title": "Your portal: all your marketing in one place", "text": "You get a link and a login. On your phone or computer, Pouch shows what''s waiting for you, what''s in production and what''s already live.", "images": [{"src": "/guias/clientes/joey/home.jpg", "alt": "Portal home screen showing what''s waiting for approval", "frame": "phone"}, {"src": "/guias/clientes/joey/menu.jpg", "alt": "Portal menu with every section", "frame": "phone"}], "layout": "stack", "bullets": ["On the home screen, the orange number is what''s waiting for your approval. Always start there.", "The menu (top corner) takes you to each section. You only see the sections for the services you signed up for.", "Save the link to your phone''s home screen. It works like an app."]}, {"who": "You", "tone": "cliente", "title": "Paid ads: what we spent and what came back", "text": "In Paid Ads you track your Meta (Instagram and Facebook) and Google ads without logging into either platform.", "images": [{"src": "/guias/clientes/joey/trafego.jpg", "alt": "Paid ads dashboard with budget, spend and results", "frame": "phone"}, {"src": "/guias/clientes/joey/trafego-plataformas.jpg", "alt": "Daily chart and numbers by platform", "frame": "phone"}], "layout": "stack", "bullets": ["Budget usage: how much of the monthly budget has been spent and how much is left.", "Spend, results (WhatsApp contacts and form leads), clicks and impressions, always compared with the previous period.", "Cost per result: what each contact cost. It''s the most important number for knowing whether an ad is worth it.", "Pick 7, 30 or 90 days and see each platform separately."]}, {"who": "You", "tone": "cliente", "title": "Approving ads takes a minute per piece", "text": "No ad goes live without your approval. The pieces arrive in Creatives or through a WhatsApp link.", "images": [{"src": "/guias/clientes/joey/criativos-capa.jpg", "alt": "Campaign with pieces to approve", "frame": "phone"}, {"src": "/guias/clientes/joey/criativo-peca.jpg", "alt": "A piece with the Approve and Request change buttons", "frame": "phone"}, {"src": "/guias/clientes/joey/criativo-ajuste.jpg", "alt": "Change request with ready-made suggestions", "frame": "phone"}], "layout": "stack", "bullets": ["Tap Start review. Pieces open one at a time, with the image and the ad copy.", "Like it? Approve. The next one opens automatically.", "Want something changed? Request change, pick what to change (image, text, colors, call to action) and write it in one sentence.", "The team gets it right away and sends you the new version to approve again."]}, {"who": "You", "tone": "cliente", "title": "CRM: log every contact that comes in", "text": "Ads bring in contacts. The CRM shows how many became sales. That''s how we know which ads make money and which only get clicks.", "images": [{"src": "/guias/clientes/joey/crm-kanban.jpg", "alt": "CRM pipeline with its stages", "frame": "phone"}], "layout": "image-left", "bullets": ["Each contact is a card: name, phone, source and what they''re interested in.", "Move the card as the conversation progresses: new, in contact, proposal sent, closed or lost.", "Closed? Enter the value. Lost? Pick the reason. It takes seconds and shapes next month''s strategy.", "In Report you see this month''s contacts, closed deals, conversion rate and the money in negotiation."]}, {"who": "Together", "tone": "equipe", "dark": true, "title": "How we make it work", "text": "The faster you reply, the faster things go live. Any questions, message Joey on WhatsApp.", "cards": [{"title": "Approve quickly", "text": "Whatever is waiting for you shows in orange on the home screen."}, {"title": "Log your contacts", "text": "An up-to-date CRM means better ads next month."}, {"title": "Send us material", "text": "Real photos and videos of your business make everything stronger."}]}]}'::jsonb, 1, true),
(7, 'joey-trafego-e-redes-en', 'How it works: paid ads and social media', 'cliente', 'en', array['Tráfego Pago','Social Media']::text[], '{"hero": {"eyebrow": "Pouch · Client guide", "title": "Ads and social media, in one place.", "text": "This guide shows how to approve posts and ads, track results and log your contacts in Pouch."}, "steps": [{"title": "Portal", "who": "You", "tone": "cliente"}, {"title": "Posts", "who": "You", "tone": "cliente"}, {"title": "Ads", "who": "You", "tone": "cliente"}, {"title": "Results", "who": "You", "tone": "cliente"}, {"title": "CRM", "who": "You", "tone": "cliente"}], "sections": [{"who": "You", "tone": "cliente", "title": "Your portal: all your marketing in one place", "text": "You get a link and a login. On your phone or computer, Pouch shows what''s waiting for you, what''s in production and what''s already live.", "images": [{"src": "/guias/clientes/joey/home.jpg", "alt": "Portal home screen showing what''s waiting for approval", "frame": "phone"}, {"src": "/guias/clientes/joey/menu.jpg", "alt": "Portal menu with every section", "frame": "phone"}], "layout": "stack", "bullets": ["On the home screen, the orange number is what''s waiting for your approval. Always start there.", "The menu (top corner) takes you to each section. You only see the sections for the services you signed up for.", "Save the link to your phone''s home screen. It works like an app."]}, {"who": "You", "tone": "cliente", "title": "Content: your post calendar", "text": "Every post planned for the month shows up here, with its date, format and status.", "images": [{"src": "/guias/clientes/joey/conteudo-mapa.jpg", "alt": "Month view with the status legend", "frame": "phone"}, {"src": "/guias/clientes/joey/conteudo-lista.jpg", "alt": "List of this month''s posts with the status of each one", "frame": "phone"}], "layout": "stack", "bullets": ["Colors show the status: in production, awaiting approval, changes requested, approved, scheduled and published.", "Orange ones are waiting for you.", "Use the arrows to see next month as soon as it''s released."]}, {"who": "You", "tone": "cliente", "title": "Approving a post", "text": "Tap the post. You see exactly how it will look on Instagram, caption included.", "images": [{"src": "/guias/clientes/joey/post-preview.jpg", "alt": "Post preview as it will appear on Instagram", "frame": "phone"}, {"src": "/guias/clientes/joey/post-aprovar.jpg", "alt": "Approve, Change and Reject buttons", "frame": "phone"}], "layout": "stack", "bullets": ["The buttons are under Details: Approve, Change or Reject.", "Asked for a change? Write what to change in the post''s comments. The conversation stays there instead of getting lost in WhatsApp.", "The history shows every version and who approved it."]}, {"who": "You", "tone": "cliente", "title": "Approving ads takes a minute per piece", "text": "No ad goes live without your approval. The pieces arrive in Creatives or through a WhatsApp link.", "images": [{"src": "/guias/clientes/joey/criativos-capa.jpg", "alt": "Campaign with pieces to approve", "frame": "phone"}, {"src": "/guias/clientes/joey/criativo-peca.jpg", "alt": "A piece with the Approve and Request change buttons", "frame": "phone"}, {"src": "/guias/clientes/joey/criativo-ajuste.jpg", "alt": "Change request with ready-made suggestions", "frame": "phone"}], "layout": "stack", "bullets": ["Tap Start review. Pieces open one at a time, with the image and the ad copy.", "Like it? Approve. The next one opens automatically.", "Want something changed? Request change, pick what to change (image, text, colors, call to action) and write it in one sentence.", "The team gets it right away and sends you the new version to approve again."]}, {"who": "You", "tone": "cliente", "title": "Paid ads: what we spent and what came back", "text": "In Paid Ads you track your Meta (Instagram and Facebook) and Google ads without logging into either platform.", "images": [{"src": "/guias/clientes/joey/trafego.jpg", "alt": "Paid ads dashboard with budget, spend and results", "frame": "phone"}, {"src": "/guias/clientes/joey/trafego-plataformas.jpg", "alt": "Daily chart and numbers by platform", "frame": "phone"}], "layout": "stack", "bullets": ["Budget usage: how much of the monthly budget has been spent and how much is left.", "Spend, results (WhatsApp contacts and form leads), clicks and impressions, always compared with the previous period.", "Cost per result: what each contact cost. It''s the most important number for knowing whether an ad is worth it.", "Pick 7, 30 or 90 days and see each platform separately."]}, {"who": "You", "tone": "cliente", "title": "Social media: how your profile is growing", "text": "Instagram numbers are collected every day and shown in Social Media.", "images": [{"src": "/guias/clientes/joey/redes.jpg", "alt": "Social media dashboard with reach, impressions, engagement and followers", "frame": "phone"}], "layout": "image-left", "bullets": ["Reach: how many people saw your content.", "Engagement: likes, comments, shares and saves.", "New followers in the period, compared with the previous period.", "The chart shows, day by day, what worked best."]}, {"who": "You", "tone": "cliente", "title": "CRM: log every contact that comes in", "text": "Ads bring in contacts. The CRM shows how many became sales. That''s how we know which ads make money and which only get clicks.", "images": [{"src": "/guias/clientes/joey/crm-kanban.jpg", "alt": "CRM pipeline with its stages", "frame": "phone"}], "layout": "image-left", "bullets": ["Each contact is a card: name, phone, source and what they''re interested in.", "Move the card as the conversation progresses: new, in contact, proposal sent, closed or lost.", "Closed? Enter the value. Lost? Pick the reason. It takes seconds and shapes next month''s strategy.", "In Report you see this month''s contacts, closed deals, conversion rate and the money in negotiation."]}, {"who": "Together", "tone": "equipe", "dark": true, "title": "How we make it work", "text": "The faster you reply, the faster things go live. Any questions, message Joey on WhatsApp.", "cards": [{"title": "Approve quickly", "text": "Whatever is waiting for you shows in orange on the home screen."}, {"title": "Log your contacts", "text": "An up-to-date CRM means better ads next month."}, {"title": "Send us material", "text": "Real photos and videos of your business make everything stronger."}]}]}'::jsonb, 1, true),
(7, 'joey-trafego-site-e-redes-en', 'How it works: ads, website and social media', 'cliente', 'en', array['Tráfego Pago','Website','Social Media']::text[], '{"hero": {"eyebrow": "Pouch · Client guide", "title": "Your website, ads and social media working together.", "text": "Your website welcomes everyone who comes from your ads and social media. This guide shows what you track and approve in Pouch."}, "steps": [{"title": "Portal", "who": "You", "tone": "cliente"}, {"title": "Website", "who": "You", "tone": "cliente"}, {"title": "Posts", "who": "You", "tone": "cliente"}, {"title": "Ads", "who": "You", "tone": "cliente"}, {"title": "Results", "who": "You", "tone": "cliente"}, {"title": "CRM", "who": "You", "tone": "cliente"}], "sections": [{"who": "You", "tone": "cliente", "title": "Your portal: all your marketing in one place", "text": "You get a link and a login. On your phone or computer, Pouch shows what''s waiting for you, what''s in production and what''s already live.", "images": [{"src": "/guias/clientes/joey/home.jpg", "alt": "Portal home screen showing what''s waiting for approval", "frame": "phone"}, {"src": "/guias/clientes/joey/menu.jpg", "alt": "Portal menu with every section", "frame": "phone"}], "layout": "stack", "bullets": ["On the home screen, the orange number is what''s waiting for your approval. Always start there.", "The menu (top corner) takes you to each section. You only see the sections for the services you signed up for.", "Save the link to your phone''s home screen. It works like an app."]}, {"who": "Team", "tone": "equipe", "title": "Your website", "text": "Your website is built in stages, and you approve each one before we move on.", "cards": [{"title": "1. Content", "text": "You send copy, photos and anything that must be included. We organize it."}, {"title": "2. Layout", "text": "We send the first version as a link. You approve it or ask for changes."}, {"title": "3. Live", "text": "We publish it on your domain, with WhatsApp and ad tracking connected."}]}, {"who": "You", "tone": "cliente", "title": "Content: your post calendar", "text": "Every post planned for the month shows up here, with its date, format and status.", "images": [{"src": "/guias/clientes/joey/conteudo-mapa.jpg", "alt": "Month view with the status legend", "frame": "phone"}, {"src": "/guias/clientes/joey/conteudo-lista.jpg", "alt": "List of this month''s posts with the status of each one", "frame": "phone"}], "layout": "stack", "bullets": ["Colors show the status: in production, awaiting approval, changes requested, approved, scheduled and published.", "Orange ones are waiting for you.", "Use the arrows to see next month as soon as it''s released."]}, {"who": "You", "tone": "cliente", "title": "Approving a post", "text": "Tap the post. You see exactly how it will look on Instagram, caption included.", "images": [{"src": "/guias/clientes/joey/post-preview.jpg", "alt": "Post preview as it will appear on Instagram", "frame": "phone"}, {"src": "/guias/clientes/joey/post-aprovar.jpg", "alt": "Approve, Change and Reject buttons", "frame": "phone"}], "layout": "stack", "bullets": ["The buttons are under Details: Approve, Change or Reject.", "Asked for a change? Write what to change in the post''s comments. The conversation stays there instead of getting lost in WhatsApp.", "The history shows every version and who approved it."]}, {"who": "You", "tone": "cliente", "title": "Approving ads takes a minute per piece", "text": "No ad goes live without your approval. The pieces arrive in Creatives or through a WhatsApp link.", "images": [{"src": "/guias/clientes/joey/criativos-capa.jpg", "alt": "Campaign with pieces to approve", "frame": "phone"}, {"src": "/guias/clientes/joey/criativo-peca.jpg", "alt": "A piece with the Approve and Request change buttons", "frame": "phone"}, {"src": "/guias/clientes/joey/criativo-ajuste.jpg", "alt": "Change request with ready-made suggestions", "frame": "phone"}], "layout": "stack", "bullets": ["Tap Start review. Pieces open one at a time, with the image and the ad copy.", "Like it? Approve. The next one opens automatically.", "Want something changed? Request change, pick what to change (image, text, colors, call to action) and write it in one sentence.", "The team gets it right away and sends you the new version to approve again."]}, {"who": "You", "tone": "cliente", "title": "Paid ads: what we spent and what came back", "text": "In Paid Ads you track your Meta (Instagram and Facebook) and Google ads without logging into either platform.", "images": [{"src": "/guias/clientes/joey/trafego.jpg", "alt": "Paid ads dashboard with budget, spend and results", "frame": "phone"}, {"src": "/guias/clientes/joey/trafego-plataformas.jpg", "alt": "Daily chart and numbers by platform", "frame": "phone"}], "layout": "stack", "bullets": ["Budget usage: how much of the monthly budget has been spent and how much is left.", "Spend, results (WhatsApp contacts and form leads), clicks and impressions, always compared with the previous period.", "Cost per result: what each contact cost. It''s the most important number for knowing whether an ad is worth it.", "Pick 7, 30 or 90 days and see each platform separately."]}, {"who": "You", "tone": "cliente", "title": "Social media: how your profile is growing", "text": "Instagram numbers are collected every day and shown in Social Media.", "images": [{"src": "/guias/clientes/joey/redes.jpg", "alt": "Social media dashboard with reach, impressions, engagement and followers", "frame": "phone"}], "layout": "image-left", "bullets": ["Reach: how many people saw your content.", "Engagement: likes, comments, shares and saves.", "New followers in the period, compared with the previous period.", "The chart shows, day by day, what worked best."]}, {"who": "You", "tone": "cliente", "title": "CRM: log every contact that comes in", "text": "Ads bring in contacts. The CRM shows how many became sales. That''s how we know which ads make money and which only get clicks.", "images": [{"src": "/guias/clientes/joey/crm-kanban.jpg", "alt": "CRM pipeline with its stages", "frame": "phone"}], "layout": "image-left", "bullets": ["Each contact is a card: name, phone, source and what they''re interested in.", "Move the card as the conversation progresses: new, in contact, proposal sent, closed or lost.", "Closed? Enter the value. Lost? Pick the reason. It takes seconds and shapes next month''s strategy.", "In Report you see this month''s contacts, closed deals, conversion rate and the money in negotiation."]}, {"who": "Together", "tone": "equipe", "dark": true, "title": "How we make it work", "text": "The faster you reply, the faster things go live. Any questions, message Joey on WhatsApp.", "cards": [{"title": "Approve quickly", "text": "Whatever is waiting for you shows in orange on the home screen."}, {"title": "Log your contacts", "text": "An up-to-date CRM means better ads next month."}, {"title": "Send us material", "text": "Real photos and videos of your business make everything stronger."}]}]}'::jsonb, 1, true),
(7, 'joey-redes-sociais-en', 'How it works: social media', 'cliente', 'en', array['Social Media']::text[], '{"hero": {"eyebrow": "Pouch · Client guide", "title": "Your post calendar, without digging through WhatsApp.", "text": "This guide shows how to see the month''s plan, approve posts and track your profile''s growth in Pouch."}, "steps": [{"title": "Portal", "who": "You", "tone": "cliente"}, {"title": "Calendar", "who": "You", "tone": "cliente"}, {"title": "Approve", "who": "You", "tone": "cliente"}, {"title": "Results", "who": "You", "tone": "cliente"}], "sections": [{"who": "You", "tone": "cliente", "title": "Your portal: all your marketing in one place", "text": "You get a link and a login. On your phone or computer, Pouch shows what''s waiting for you, what''s in production and what''s already live.", "images": [{"src": "/guias/clientes/joey/home.jpg", "alt": "Portal home screen showing what''s waiting for approval", "frame": "phone"}, {"src": "/guias/clientes/joey/menu.jpg", "alt": "Portal menu with every section", "frame": "phone"}], "layout": "stack", "bullets": ["On the home screen, the orange number is what''s waiting for your approval. Always start there.", "The menu (top corner) takes you to each section. You only see the sections for the services you signed up for.", "Save the link to your phone''s home screen. It works like an app."]}, {"who": "You", "tone": "cliente", "title": "Content: your post calendar", "text": "Every post planned for the month shows up here, with its date, format and status.", "images": [{"src": "/guias/clientes/joey/conteudo-mapa.jpg", "alt": "Month view with the status legend", "frame": "phone"}, {"src": "/guias/clientes/joey/conteudo-lista.jpg", "alt": "List of this month''s posts with the status of each one", "frame": "phone"}], "layout": "stack", "bullets": ["Colors show the status: in production, awaiting approval, changes requested, approved, scheduled and published.", "Orange ones are waiting for you.", "Use the arrows to see next month as soon as it''s released."]}, {"who": "You", "tone": "cliente", "title": "Approving a post", "text": "Tap the post. You see exactly how it will look on Instagram, caption included.", "images": [{"src": "/guias/clientes/joey/post-preview.jpg", "alt": "Post preview as it will appear on Instagram", "frame": "phone"}, {"src": "/guias/clientes/joey/post-aprovar.jpg", "alt": "Approve, Change and Reject buttons", "frame": "phone"}], "layout": "stack", "bullets": ["The buttons are under Details: Approve, Change or Reject.", "Asked for a change? Write what to change in the post''s comments. The conversation stays there instead of getting lost in WhatsApp.", "The history shows every version and who approved it."]}, {"who": "You", "tone": "cliente", "title": "Social media: how your profile is growing", "text": "Instagram numbers are collected every day and shown in Social Media.", "images": [{"src": "/guias/clientes/joey/redes.jpg", "alt": "Social media dashboard with reach, impressions, engagement and followers", "frame": "phone"}], "layout": "image-left", "bullets": ["Reach: how many people saw your content.", "Engagement: likes, comments, shares and saves.", "New followers in the period, compared with the previous period.", "The chart shows, day by day, what worked best."]}, {"who": "Together", "tone": "equipe", "dark": true, "title": "How we make it work", "text": "The faster you reply, the faster things go live. Any questions, message Joey on WhatsApp.", "cards": [{"title": "Approve quickly", "text": "Whatever is waiting for you shows in orange on the home screen."}, {"title": "Send us material", "text": "Real photos and videos of your business make everything stronger."}, {"title": "Comment on the post", "text": "Change requests on a post never get lost."}]}]}'::jsonb, 1, true);
